import * as THREE from 'three';
const barkMat = new THREE.MeshStandardMaterial({ color: 0x3b3128, roughness: 1, flatShading: true });
const snowMat = new THREE.MeshStandardMaterial({ color: 0xe9eef4, roughness: 0.9, flatShading: true });
const SNOW_MIN_RADIUS = 0.04;                       // ridges only on limbs at least this thick; twigs stay bare
export function makeWinterTree(rng = Math.random, levels = 4) {
  const tree = new THREE.Group(); tree.userData.tag = 'tree';
  function limb(parent, radius, length, level) {
    const geo = new THREE.CylinderGeometry(radius * 0.6, radius, length, 6); geo.translate(0, length / 2, 0);
    const m = new THREE.Mesh(geo, barkMat); m.userData = { tag: level === 0 ? 'trunk' : 'branch', radius }; parent.add(m);
    if (level > 0 && radius >= SNOW_MIN_RADIUS) {
      const ridge = new THREE.Mesh(new THREE.SphereGeometry(radius * 1.6, 8, 5), snowMat);   // flattened ridge along the top
      ridge.scale.set(1, 0.35, length / (radius * 3.2)); ridge.rotation.x = Math.PI / 2;
      ridge.position.set(radius * 0.9, length * 0.55, 0); ridge.userData = { tag: 'snow-ridge', branchRadius: radius }; m.add(ridge);
      m.rotation.z += THREE.MathUtils.degToRad(10 + rng() * 5) * (rng() < 0.5 ? 1 : -1);   // weight droop 10-15 deg
    }
    if (level >= levels - 1) return;
    const kids = 2 + Math.floor(rng() * 2);        // 2-3 children per level, never 6-8
    for (let i = 0; i < kids; i++) {
      const child = new THREE.Group();
      child.position.y = length * (0.55 + rng() * 0.4);
      child.rotation.set((rng() - 0.5) * 0.9, (i / kids) * Math.PI * 2 + rng(), 0.45 + rng() * 0.5);
      m.add(child);
      limb(child, radius * 0.55, Math.min(length * (0.6 + rng() * 0.3), length * 1.5), level + 1);   // radius ~halves per level; child <= 1.5x parent
    }
  }
  limb(tree, 0.16, 3.2, 0);                          // trunk radius >= 0.12 at the base: 0.16 -> 0.088 -> 0.048 (snow) -> 0.027 (bare)
  return tree;
}
